MAX_TOKENS = 4096

# %%
@kbench.task(name="gfg-item", store_task=False)
def gfg_item(llm, record) -> dict:
    cap_key = ('max_output_tokens' if isinstance(llm, GoogleGenAI) else
               'max_tokens' if isinstance(llm, OpenAI) else None)
    params = {cap_key: MAX_TOKENS} if cap_key else {}
    if isinstance(llm, OpenAI):
        params['timeout'] = 60
    for attempt in range(2):
        try:
            response = llm.prompt(record['item']['prompt'], temperature=0, extra_api_params=params)
            break
        except Exception as exc:
            if attempt:
                result = score_item('', record['gold'])
                result.update(format_ok=False, format_error='api_error',
                              api_error=type(exc).__name__ + ': ' + str(exc)[:200],
                              lost_exact=False, rec_exact=False, item_correct=False,
                              perm_flag_consistent=False)
                return result
            if cap_key and any(word in str(exc).lower() for word in
                               ('max_tokens', 'max_output_tokens', 'unsupported parameter')):
                params.pop(cap_key, None)
            time.sleep(5)
    result = score_item(response, record['gold'])
    result['raw_response'] = response
    return result

# %%
@kbench.task(name='gone-for-good')
def gone_for_good(llm) -> float:
    rows = []
    for record in RECORDS:
        row = gfg_item(llm, record)
        print('GFG_ITEM ' + json.dumps(row, sort_keys=True))
        rows.append(row)
    summary = aggregate(rows, expected_items=[r['gold'] for r in RECORDS])
    summary['n_api_errors'] = sum(r.get('format_error') == 'api_error' for r in rows)
    print('GFG_AGGREGATE ' + json.dumps(summary, sort_keys=True))
    if summary['n_api_errors'] > len(RECORDS) * 0.2:
        print('GFG_WARNING incomplete run')
    return summary['pair_acc']

gone_for_good.run(kbench.llm)
